import fs from "node:fs";
import path from "node:path";
import { execSync } from "node:child_process";

const branch = execSync("git branch --show-current", { encoding: "utf8" }).trim();
if (branch !== "vNext") throw new Error(`Expected vNext branch, got ${branch}`);
const status = execSync("git status --porcelain", { encoding: "utf8" }).trim();
if (status) throw new Error("Working tree must be clean before applying Work Area + QR Foundation 01.");

const payload = JSON.parse(Buffer.from("", "base64").toString("utf8"));
for (const [rel, content] of Object.entries(payload)) {
  fs.mkdirSync(path.dirname(rel), { recursive: true });
  fs.writeFileSync(rel, content, "utf8");
}

const cssPath = "src/app/globals.css";
const marker = "/* Work Area + QR Lifecycle Foundation 01 */";
let currentCss = fs.readFileSync(cssPath, "utf8");
if (!currentCss.includes(marker)) {
  currentCss += "\n/* Work Area + QR Lifecycle Foundation 01 */\n.formStack select, .formStack textarea {\n  width: 100%;\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  padding: 12px 14px;\n  background: var(--surface);\n  color: var(--text);\n  font: inherit;\n}\n.workspaceNotice { max-width: 1180px; margin: 0 auto 18px; }\n.workAreaGrid {\n  max-width: 1180px;\n  margin: 18px auto 0;\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0,1fr));\n  gap: 18px;\n}\n.workAreaCard {\n  border: 1px solid var(--border);\n  border-radius: 18px;\n  padding: 22px;\n  background: var(--surface);\n}\n.workAreaCardHead { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }\n.workAreaCardHead h2 { margin: 10px 0 4px; }\n.workAreaCardHead p { margin: 0; color: var(--muted); }\n.statusPill {\n  display: inline-flex;\n  border-radius: 999px;\n  padding: 5px 9px;\n  font-size: .72rem;\n  font-weight: 800;\n  letter-spacing: .06em;\n}\n.activePill { background: #ecfdf5; color: #047857; }\n.inactivePill { background: #f1f5f9; color: #64748b; }\n.cardActions { display: flex; flex-wrap: wrap; gap: 10px; margin: 18px 0 10px; }\n.dangerButton { background: transparent; color: #b42318; border: 1px solid #fda29b; }\n.labelPage { min-height: 100vh; padding: 24px; background: #f8fafc; color: #0f172a; }\n.labelToolbar { max-width: 720px; margin: 0 auto 18px; display: flex; justify-content: space-between; gap: 12px; }\n.qrLabel {\n  width: 4in;\n  min-height: 6in;\n  margin: 0 auto;\n  background: white;\n  border: 1px solid #cbd5e1;\n  padding: .28in;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  text-align: center;\n  gap: .08in;\n}\n.qrBrand { font-weight: 850; font-size: .28in; }\n.qrLabel h1 { font-size: .32in; margin: .08in 0; }\n.qrSvg { width: 3in; height: 3in; }\n.qrSvg svg { width: 100%; height: 100%; display: block; }\n.labelHint { max-width: 720px; margin: 14px auto; text-align: center; color: #64748b; }\n.publicServiceCard {\n  width: min(100%, 680px);\n  margin: 0 auto;\n  border: 1px solid var(--border);\n  border-radius: 24px;\n  padding: clamp(26px,5vw,48px);\n  background: var(--surface);\n}\n.publicHierarchy { color: var(--muted); }\n.publicDetail { display: grid; gap: 5px; border-top: 1px solid var(--border); padding-top: 18px; margin-top: 18px; }\n.demoOperations { margin: 32px 0; }\n.demoWorkAreaCard {\n  margin-top: 14px;\n  border: 1px solid var(--border);\n  border-radius: 18px;\n  padding: 22px;\n  display: flex;\n  justify-content: space-between;\n  gap: 20px;\n  align-items: center;\n}\n.demoQrPattern {\n  width: 110px; height: 110px; border: 10px solid #0f172a;\n  background:\n    linear-gradient(90deg,#0f172a 12px,transparent 12px 24px,#0f172a 24px 36px,transparent 36px 48px,#0f172a 48px 60px,transparent 60px 72px,#0f172a 72px 84px,transparent 84px),\n    linear-gradient(#0f172a 12px,transparent 12px 24px,#0f172a 24px 36px,transparent 36px 48px,#0f172a 48px 60px,transparent 60px 72px,#0f172a 72px 84px,transparent 84px);\n  background-size: 84px 84px;\n}\n.demoBehaviorGrid { display: grid; grid-template-columns: repeat(3,1fr); gap: 12px; margin-top: 12px; }\n.demoBehaviorGrid article { border: 1px solid var(--border); border-radius: 14px; padding: 16px; display: grid; gap: 6px; }\n.demoBehaviorGrid span { color: var(--muted); }\n@media (max-width: 760px) {\n  .workAreaGrid, .demoBehaviorGrid { grid-template-columns: 1fr; }\n  .workAreaCardHead { flex-direction: column; }\n}\n@media print {\n  @page { size: 4in 6in; margin: 0; }\n  .noPrint { display: none !important; }\n  .labelPage { padding: 0; background: white; }\n  .qrLabel { border: 0; width: 4in; height: 6in; margin: 0; }\n}\n";
  fs.writeFileSync(cssPath, currentCss, "utf8");
}

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
pkg.scripts["db:work-area-qr:apply"] = "node scripts/db-apply-work-area-qr-04.mjs";
fs.writeFileSync("package.json", JSON.stringify(pkg, null, 2) + "\n", "utf8");

console.log("Installing QR rendering dependency...");
execSync("npm install qrcode@1.5.4 @types/qrcode@1.5.6 --save", { stdio: "inherit" });
execSync("node --check scripts/db-apply-work-area-qr-04.mjs", { stdio: "inherit" });
console.log("Work Area + QR Lifecycle Foundation 01 files applied.");
console.log("Next: npm run db:work-area-qr:apply");
